// Mia — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, V1_INSTALL_AT_MS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Mia app's origin (see `apps/registry/apps/mia.ts`). */
    readonly VITE_MIA_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/mia` calls: its `ProxyMethod` table in
// `web/mia/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only — ⚠ no `mia.*` wildcard, so a Mia method added later (a confirm, a delete) is not
// reachable by default (`proxyGateway.mia.test.ts` pins both this list and that no OTHER app names
// any `mia.*`).
// ⚠⚠ Threat model A39: `mia.ask` reads, through questions, every source the grants allow — files,
// timeline, workouts, places, calendar, devices, routines, labels. That is why only this origin may
// call it. Every action is withheld in the tab, so no answer writes; the grant switches write the
// realm's Mia grant rows and nothing else.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  // Chat
  'mia.ask',
  // History (in memory, MQ-D8)
  'mia.history',
  'mia.history.observe',
  'mia.turnsPage',
  // What Mia can read, and its switches
  'mia.grants',
  'mia.grants.observe',
  'mia.grants.setGranted',
  'mia.grants.setWritable',
]

const PROD_ORIGIN = 'https://mia.tenshu.app'

export const mia: HostedApp = {
  id: 'mia',
  order: 50,
  title: 'Mia',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_MIA_ORIGIN',
  devPort: 5182,
  origin: () => appOrigin(import.meta.env.VITE_MIA_ORIGIN, PROD_ORIGIN, 5182),
  methods: METHODS,
  routePath: 'mia/*',
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'mia',
    label: 'Mia',
    description: 'Ask about your own data, answered on this device.',
    version: '0.1.0',
    installedAtMs: V1_INSTALL_AT_MS,
    launchPath: '/mia',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'mia.ask',
        label: 'Answer questions about your data',
        description:
          'Read, to answer a question, whatever you let Mia read: files, photos, timeline, workouts, places, calendar, devices and routines. Read only.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'mia.grants',
        label: 'Change what Mia can read',
        description: 'Turn Mia’s access to each source on or off, on all your devices.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'mia',
        label: 'MiaService',
        reason: 'Answers questions with the on-device planner. No model, and nothing is written.',
      },
      {
        id: 'preference',
        label: 'PreferenceService',
        reason: 'Stores which sources Mia may read.',
      },
    ],
  },
}

export default mia
